export function mahjongTexts(lang: string): MahjongTexts {
  return STRINGS[lang as Lang] ?? en;
}

export function fillText(s: string, v: Record<string, string | number>): string {
  return s.replace(/\{(\w+)\}/g, (m, k: string) => (k in v ? String(v[k]) : m));
}
